import { GraphiQLHTMLFactory } from './graphiql-html.factory.js';
export class GraphiQLPlaygroundPlugin {
    constructor(options) {
        this.options = options;
        this.graphiqlHTMLFactory = new GraphiQLHTMLFactory();
    }
    async serverWillStart() {
        const html = this.graphiqlHTMLFactory.create(this.options);
        return {
            async renderLandingPage() {
                return { html };
            },
        };
    }
}
